		/// </summary>
		public byte[] EntityImage_Download(Microsoft.Xrm.Sdk.IOrganizationService service)
		{
			var request = new Microsoft.Crm.Sdk.Messages.InitializeFileBlocksDownloadRequest
			{
				Target = Entity.ToEntityReference(),
				FileAttributeName = "entityimage"
			};
			var response = (Microsoft.Crm.Sdk.Messages.InitializeFileBlocksDownloadResponse)service.Execute(request);
			var data = new byte[response.FileSizeInBytes];
			long offset = 0;
			while (offset < response.FileSizeInBytes)
			{
				var blockRequest = new Microsoft.Crm.Sdk.Messages.DownloadBlockRequest
				{
					FileContinuationToken = response.FileContinuationToken,
					BlockLength = (int)Math.Min(4 * 1024 * 1024, response.FileSizeInBytes - offset),
					Offset = offset
				};
				var blockResponse = (Microsoft.Crm.Sdk.Messages.DownloadBlockResponse)service.Execute(blockRequest);
				Array.Copy(blockResponse.Data, 0, data, offset, blockResponse.Data.Length);
				offset += blockResponse.Data.Length;
			}
			return data;
		}
